def icon(name, cls=''):
    return f'<i class="ri-{name}-line {cls}" aria-hidden="true"></i>'
def photo(name, alt, cls='', eager=False):
    return f'<img class="{cls}" src="/assets/{name}" alt="{escape(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async">'
def link(url, text, cls='button button-yellow', arrow=True, external=False):
    ext=' target="_blank" rel="noopener noreferrer"' if external else ''
    return f'<a class="{cls}" href="{url}"{ext}>{text}{icon("arrow-right") if arrow else ""}</a>'
def label(text):
    return f'<p class="eyebrow">{text}</p>'
def brand(footer=False):
    return f'<a class="brand {"brand-footer" if footer else ""}" href="/" aria-label="BIT homepage">{photo("bit-logo.png","Birgunj Institute of Technology logo",eager=True)}<span>BIRGUNJ INSTITUTE<br>OF TECHNOLOGY</span></a>'

