PAGES=[]
def write_page(path,title,description,content,active='',hero_title=None,hero_desc=None):
    p=DIST/path.strip('/') if path.strip('/') else DIST
    p.mkdir(parents=True,exist_ok=True)
    subhero=''
    if hero_title:
        subhero=f'<section class="page-hero"><div class="container"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a>{icon("arrow-right-s")}<span>{escape(title)}</span></nav>{label("BIRGUNJ INSTITUTE OF TECHNOLOGY")}<h1>{hero_title}</h1><p>{hero_desc or description}</p></div></section>'
    url=ORIGIN+path
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Birgunj Institute of Technology</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="{BLUE}"><meta name="robots" content="noindex,nofollow"><link rel="icon" href="/assets/bit-logo.png"><link rel="canonical" href="{url}"><meta property="og:title" content="{escape(title)} | BIT"><meta property="og:description" content="{escape(description)}"><meta property="og:image" content="{ORIGIN}/assets/campus.webp"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><link rel="preload" href="/assets/fonts.css" as="style"><link rel="stylesheet" href="/assets/fonts.css"><link rel="stylesheet" href="/assets/remixicon.css"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script></head><body>{header(active)}<main id="main">{subhero}{content}</main>{footer()}<dialog class="lightbox" id="photo-lightbox" aria-label="Campus photograph"><button class="icon-button" data-close-dialog aria-label="Close image">{icon('close')}</button><img src="/assets/campus.webp" alt=""><p></p></dialog></body></html>'''
    (p/'index.html').write_text(doc)
    PAGES.append({'path':path,'title':title})

