def notice_rows(items,search=False):
    return '<div class="notice-list">'+''.join(f'<a class="notice-row" href="/notices/{n["date"]}-{i}/" data-notice data-search="{escape(n["title"].lower())}" data-year="{n["date"][:4]}" data-category="{n["type"]}">{icon("file-text")}<span class="notice-title">{n["title"]}{f"<small>{n['type']}</small>" if search else ""}</span><time datetime="{n["date"]}">{n["display"]}</time>{icon("arrow-right","notice-arrow")}</a>' for i,n in enumerate(items))+'</div>'

