admissions=f'<section class="section"><div class="container"><div class="section-heading">{label("YOUR NEXT STEP")}<h2>A CLEAR PATH TO YOUR ADMISSION INQUIRY.</h2></div><div class="steps-grid">'
for i,(title,desc) in enumerate([('Explore your program','Compare the five diploma disciplines and choose what connects with your interests.'),('Speak with admissions','Ask BIT about the current intake, eligibility, entrance requirements, fees and available seats.'),('Prepare your documents','Collect your academic records and the documents requested by the admissions office.'),('Follow the official process','Obtain the application form from BIT administration and follow the applicable CTEVT requirements.')]):admissions+=f'<article><span>0{i+1}</span><h3>{title}</h3><p>{desc}</p></article>'
admissions+=f'</div></div></section><section class="section section-tint"><div class="container content-split"><div>{label("DOCUMENT CHECKLIST")}<h2>COME PREPARED.</h2><p>The published admission guide lists the following documents. Confirm the current checklist with the admissions office.</p><ul class="document-checklist">'+''.join(f'<li>{icon("checkbox-circle")}<span>{s}</span></li>' for s in ['SEE / SLC certificate or equivalent · two copies','Citizenship certificate · two copies','Recent passport-size photographs · four','Domicile certificate or passport for foreign students · two copies'])+f'</ul>{link("/brochure-prospectus/","Explore the prospectus","text-link")}</div><div class="contact-panel">{icon("chat-1")}<h2>LET’S TALK ABOUT<br>YOUR NEXT STEP.</h2><p>Our office can help you with program choice and the current admission process.</p>{link("tel:+97751528020","Call +977-51-528020","button button-yellow")}{link("/contact/?subject=Admission%20inquiry","Prepare an email inquiry","button button-outline-light")}<a href="mailto:info.bitcollege@gmail.com">info.bitcollege@gmail.com</a></div></div></section><section class="section"><div class="container narrow">{label("ADMISSION QUESTIONS")}<h2>USEFUL THINGS TO KNOW.</h2><div class="faq-list">'
for question,answer in [('How do I start?','Explore the programs and contact BIT administration for the current application form and intake details.'),('Is there a CTEVT entrance requirement?','Follow the applicable CTEVT entrance and eligibility requirements. Ask BIT for the current notice and dates.'),('What are the fees and available seats?','Contact the admissions office for current program fees, application fees and seat availability.'),('Can I ask about a scholarship?','Yes. BIT publishes information about CTEVT classified or special schemes and internal merit scholarships. Ask about current eligibility and availability.')]:admissions+=f'<details><summary>{question}{icon("add")}</summary><p>{answer}</p></details>'
admissions+='</div></div></section>'
write_page('/admission/','Admissions','Start your admission inquiry with BIT. Explore programs, documents and the official admission process.',admissions,'admissions','YOUR NEXT CHAPTER<br>STARTS AT BIT.')

scholarship=f'<section class="section"><div class="container two-grid"><article class="information-card">{icon("graduation-cap")}<h2>CTEVT SCHEMES</h2><p>BIT’s published scholarship information describes classified and special schemes under CTEVT policy, with separate application and selection requirements.</p><p>Ask the institute for the current notice, eligibility and application process.</p></article><article class="information-card">{icon("award")}<h2>INTERNAL MERIT SUPPORT</h2><p>BIT also describes internal merit-based scholarship schemes linked to semester examination results.</p><p>Speak with the college about the schemes currently available and their requirements.</p></article></div></section><section class="section section-tint"><div class="container content-split"><div>{label("PLAN YOUR NEXT STEP")}<h2>ASK THE RIGHT QUESTIONS.</h2><ul class="clean-list"><li>Which schemes are available for my program?</li><li>What are the eligibility and selection requirements?</li><li>Which documents do I need?</li><li>What is the current application deadline?</li></ul></div><div class="contact-panel"><h2>GET CURRENT<br>SCHOLARSHIP INFORMATION.</h2><p>Our office can help you understand the next steps.</p>{link("/contact/?subject=Scholarship%20inquiry","Contact BIT")}</div></div></section>'
write_page('/scholarship/','Scholarships','Learn about BIT’s published scholarship pathways and ask for current eligibility and availability.',scholarship,'admissions','SUPPORT FOR<br>YOUR LEARNING JOURNEY.')

GALLERY=[('campus.webp','campus','The BIT campus and courtyard'),('computer-lab-group.jpg','learning','Practical computing in the computer lab'),('electronics-practical.jpg','learning','Students working with electronic circuits'),('surveying-field.jpg','learning','Surveying and field practice'),('library-students.jpg','learning','Student learning resources in the library'),('industrial-visit.jpg','community','An industrial visit with BIT students'),('workshop-2.jpg','community','Student sports teams'),('workshop-3.jpg','community','Students gathering on campus'),('workshop-1.jpg','community','A college community event'),('lab.jpg','learning','Practical laboratory activity'),('field-practice.jpg','learning','Collaborative field practice'),('workshop-4.jpg','community','Students on the campus steps')]
campus=f'<section class="section"><div class="container content-split"><div>{label("THE BIT EXPERIENCE")}<h2>A CAMPUS FOR<br>LEARNING & CONNECTION.</h2><p>Explore the places and activities that bring BIT’s technical education to life: computer labs, laboratories, workshops, library resources and practical field activity.</p><p>Our campus in Birgunj is also a place to meet, learn together and take part in the college community.</p>{link("/contact/?subject=Campus%20visit","Ask about a campus visit")}</div>{photo("campus.webp","BIT’s yellow campus and green courtyard","content-photo")}</div></section><section class="section section-tint"><div class="container">{label("CAMPUS GALLERY")}<div class="section-heading"><h2>SEE LEARNING IN ACTION.</h2></div><div class="filter-tabs" role="group" aria-label="Filter campus gallery"><button class="active" data-gallery-filter="all" aria-pressed="true">All photos</button><button data-gallery-filter="campus" aria-pressed="false">Campus</button><button data-gallery-filter="learning" aria-pressed="false">Practical learning</button><button data-gallery-filter="community" aria-pressed="false">Community</button></div><div class="gallery-grid">'
for file,category,alt in GALLERY:campus+=f'<button class="gallery-item" data-gallery-category="{category}" data-lightbox="/assets/{file}" data-caption="{alt}" aria-label="Open photograph: {alt}">{photo(file,alt)}<span>{alt}{icon("expand-diagonal")}</span></button>'
campus+='</div></div></section>'
write_page('/campus-life/','Campus life','Discover BIT’s campus, labs, library, practical field activities and college community.',campus,'campus','LEARNING BEYOND<br>THE CLASSROOM.')

notices=f'<section class="section"><div class="container"><div class="archive-intro"><div>{label("PUBLISHED NOTICES")}<h2>NOTICE ARCHIVE</h2><p>Browse published college notices. For current schedules and admission information, contact the BIT office.</p></div>{link("/contact/?subject=Current%20notice%20inquiry","Contact the office","button button-blue")}</div><form class="notice-filters" role="search" id="notice-search"><label class="search-field">{icon("search")}<span class="sr-only">Search notices</span><input id="notice-query" type="search" placeholder="Search notices…" autocomplete="off"></label><label><span>Year</span><select id="notice-year"><option value="all">All years</option><option>2024</option><option>2023</option></select></label><label><span>Category</span><select id="notice-category"><option value="all">All categories</option><option>Examinations</option><option>Admissions</option><option>College</option></select></label></form><p id="notice-count" class="result-count" aria-live="polite">{len(NOTICES)} notices</p>{notice_rows(NOTICES,True)}<div class="empty-state" id="notice-empty" hidden>{icon("search")}<h3>No notices match your search.</h3><p>Try a different keyword or reset your filters.</p><button class="button button-blue" id="reset-notices">Reset filters</button></div></div></section>'
write_page('/notices/','Notice archive','Search BIT’s published notices by topic, year and category.',notices,'notices','COLLEGE NOTICES.<br>CLEAR INFORMATION.')
for i,n in enumerate(NOTICES):
    content=f'<section class="section"><article class="container narrow prose"><div class="article-meta"><time datetime="{n["date"]}">{n["display"]}</time><span>{n["type"]}</span><span>Archive</span></div><h2>{n["title"]}</h2><p>{n["note"]}</p><p>This notice belongs to the historical college archive. Contact the BIT office for current information.</p><div class="button-row">{link(n["url"],"Open official source","button button-blue",True,True)}{link("/notices/","Back to notices","text-link")}</div></article></section>'
    write_page(f'/notices/{n["date"]}-{i}/',n['title'],n['note'],content,'notices','PUBLISHED<br>COLLEGE NOTICE.')

download=f'<section class="section"><div class="container download-grid"><article class="download-card">{icon("file-pdf-2")}<div>{label("PROSPECTUS ARCHIVE")}<h2>BIT PROSPECTUS</h2><p>Explore the archived college prospectus from the official BIT source.</p><span class="resource-tag">PDF · Archived edition</span>{link("https://bit.edu.np/wp-content/uploads/2023/02/BIT-Prospectus-2078_11zon.pdf","Open prospectus","button button-blue",True,True)}</div></article><article class="download-card">{icon("file-list-3")}<div>{label("ENTRANCE PREPARATION")}<h2>MODEL QUESTIONS</h2><p>Find the programs and historical model-question sets listed by BIT.</p><span class="resource-tag">Five diploma disciplines</span>{link("/entrance-model-questions/","Explore model questions","button button-blue")}</div></article></div></section><section class="section section-tint"><div class="container content-split"><div>{label("NEED A CURRENT DOCUMENT?")}<h2>THE OFFICE CAN HELP.</h2><p>For the current prospectus, application form, curriculum or examination document, contact BIT administration.</p></div><div>{link("/contact/?subject=Document%20request","Request information")}</div></div></section>'
write_page('/brochure-prospectus/','Prospectus & downloads','Find the archived BIT prospectus and entrance preparation resources.',download,'','PROSPECTUS.<br>PREPARATION. RESOURCES.')
write_page('/downloads/','Downloads','College prospectus and entrance preparation resources.',download,'','COLLEGE<br>RESOURCES.')

models=f'<section class="section"><div class="container narrow"><p class="lead">BIT’s published model-question page lists historical sets for each diploma discipline. Use them as preparation resources and ask the office about the current entrance process.</p><div class="faq-list">'
for p in PROGRAMS:models+=f'<details><summary>{p["name"]}{icon("add")}</summary><p>Listed archived sets: 2076, 2077 and 2078.</p><div class="button-row">{link("https://bit.edu.np/entrance-model-questions/","Visit official resource page","text-link",True,True)}{link("/contact/?subject=Entrance%20model%20questions","Ask the office","text-link")}</div></details>'
models+='</div></div></section>'
write_page('/entrance-model-questions/','Entrance model questions','Explore the historical entrance model-question sets listed for BIT’s five diploma disciplines.',models,'','PREPARE FOR<br>YOUR NEXT STEP.')

research=f'<section class="section"><div class="container content-split"><div>{label("TECHNICAL CURIOSITY")}<h2>LEARNING THROUGH<br>QUESTIONS & PRACTICE.</h2><p>Practical study and project work give students opportunities to connect technical ideas with real-world problems.</p><p>For information about BIT’s research activities, student projects or publications, contact the academic office.</p>{link("/contact/?subject=Research%20and%20publication%20inquiry","Contact the academic office")}</div>{photo("electronics-practical.jpg","Students exploring practical circuit work at BIT","content-photo")}</div></section>'
write_page('/research-publication/','Research & publication','Contact BIT for information about technical projects, research activities and publications.',research,'','IDEAS. QUESTIONS.<br>PRACTICAL LEARNING.')

articles=[('certificate-and-diploma-programs-in-nepal','Certificate and Diploma Programs in Nepal','graduation-cap','Technical education offers a practical route into specialist learning. A diploma connects subject knowledge with laboratory work, field experience and projects. Before choosing a program, explore its curriculum, affiliation, admission requirements and the kind of work you enjoy. BIT offers five three-year CTEVT diploma disciplines. Speak with the admissions office for current eligibility and intake information.'),('importance-of-civil-engineering','Importance of Civil Engineering','building-2','Civil engineering study connects with the infrastructure communities rely on, including buildings, roads and water systems. Surveying, drawing, estimation and construction help students understand how ideas become real structures. BIT’s Civil diploma includes technical subjects, field survey activity and project work. Explore the program to understand its subject highlights and practical learning.'),('importance-of-computer-engineering','Importance of Computer Engineering','computer','Computing supports how people create, communicate and solve problems. Studying Computer Engineering introduces software, hardware and networks as related technical systems. BIT’s program includes programming, databases, networking and project work. Practical learning helps students connect the concepts they study with the systems they use.'),('importance-of-electrical-engineering','Importance of Electrical Engineering','flashlight','Electrical systems support homes, industry and public infrastructure. Understanding circuits, machines and power systems is a foundation for safe technical practice. BIT’s Electrical diploma introduces installation, measurement, protection, maintenance and practical projects. Explore the program’s subject highlights and speak with the institute about the current curriculum.'),('importance-of-electrical-electronics-engineering','Importance of Electrical & Electronics Engineering','cpu','Electrical power and electronic control work together in many technical systems. This discipline connects circuits, digital logic, machines and communication with practical learning. BIT’s Electrical & Electronics diploma includes electronic fundamentals, microprocessors, programmable control and industry-based projects.'),('importance-of-mechanical-engineering','Importance of Mechanical Engineering','settings-3','Machines and manufacturing turn technical ideas into useful products and processes. Mechanical study explores materials, drawing, engines and the systems that make equipment work. BIT’s Mechanical diploma includes manufacturing, CAD, automotive topics, industrial attachment and project work. It offers a foundation for further technical learning and practical work.')]
blog='<section class="section"><div class="container insights-grid">'
for slug,title,ico,body in articles:blog+=f'<a class="insight-card" href="/{slug}/">{icon(ico)}{label("ENGINEERING INSIGHTS")}<h2>{title}</h2><p>{body.split(".")[0]}.</p><span class="text-link">Read more {icon("arrow-right")}</span></a>'
blog+='</div></div></section>'
write_page('/blog/','Engineering insights','Explore technical education and the engineering disciplines offered at BIT.',blog,'','EXPLORE IDEAS.<br>UNDERSTAND YOUR PATH.')
for slug,title,ico,body in articles:
    content=f'<section class="section"><article class="container narrow prose"><div class="article-symbol">{icon(ico)}</div>{label("ENGINEERING INSIGHTS")}<h2>{title}</h2><p class="lead">{body}</p><div class="button-row">{link("/programs/","Explore BIT programs")}{link("/blog/","More insights","text-link")}</div></article></section>'
    write_page('/'+slug+'/',title,title+' and BIT’s practical technical education.',content,'',title.upper()+'.')

options=''.join(f'<option value="{p["key"]}">{p["name"]}</option>' for p in PROGRAMS)
contact=f'''<section class="section"><div class="container contact-grid"><div><h2>LET’S TALK.</h2><p>Ask about programs, admissions, college resources or a campus visit.</p><div class="contact-method"><span>{icon('map-pin')}</span><div><h3>VISIT THE CAMPUS</h3><p>Pipra / Sugar Factory Residential Area<br>Birgunj-14, Parsa, Nepal</p>{link('https://www.google.com/maps/search/?api=1&query=Birgunj%20Institute%20of%20Technology%20Nepal','Find BIT on Google Maps','text-link',True,True)}</div></div><div class="contact-method"><span>{icon('phone')}</span><div><h3>CALL BIT</h3><a href="tel:+97751528020">+977-51-528020</a><a href="tel:+97751592069">+977-51-592069</a><a href="tel:+9779855020699">+977-9855020699</a></div></div><div class="contact-method"><span>{icon('mail')}</span><div><h3>EMAIL THE OFFICE</h3><a href="mailto:info.bitcollege@gmail.com">info.bitcollege@gmail.com</a><a href="mailto:exam.bitcollege@gmail.com">exam.bitcollege@gmail.com <small>Examinations</small></a></div></div></div><form class="enquiry-form" id="enquiry-form"><h2>PREPARE AN INQUIRY.</h2><p>Tell us what you’d like to know. Review your message, then open it in your email app.</p><div class="form-row"><label>Full name <input name="name" autocomplete="name" maxlength="100" required placeholder="Your full name"></label><label>Phone <input name="phone" type="tel" autocomplete="tel" maxlength="30" placeholder="Your contact number"></label></div><label>Email <input name="email" type="email" autocomplete="email" maxlength="160" required placeholder="you@example.com"></label><label>Program of interest <select name="program"><option value="general">General inquiry</option>{options}</select></label><label>Message <textarea name="message" rows="5" maxlength="3000" required placeholder="How can the BIT office help you?"></textarea></label><button class="button button-yellow" type="submit" id="review-inquiry" disabled>Review email inquiry {icon('arrow-right')}</button><p class="form-note">Your email app sends the message after you review it.</p><noscript><p>Please <a href="mailto:info.bitcollege@gmail.com">email BIT directly</a> or <a href="tel:+97751528020">call the office</a>.</p></noscript></form></div></section><section class="campus-contact-photo">{photo('campus.webp','The Birgunj Institute of Technology campus')}</section><dialog class="email-dialog" id="email-preview" aria-labelledby="email-preview-title"><div class="dialog-title"><h2 id="email-preview-title">REVIEW YOUR INQUIRY.</h2><button class="icon-button" data-close-dialog aria-label="Close email preview">{icon('close')}</button></div><p>To: info.bitcollege@gmail.com</p><pre id="email-body"></pre><div class="button-row"><a class="button button-yellow" id="open-email" href="mailto:info.bitcollege@gmail.com">Open email app {icon('mail')}</a><button class="text-link" data-close-dialog>Edit message</button></div></dialog>'''
write_page('/contact/','Contact BIT','Contact Birgunj Institute of Technology in Birgunj-14, Parsa for programs, admissions and college information.',contact,'contact','YOUR NEXT STEP<br>STARTS WITH A CONVERSATION.')

notfound=f'<section class="section"><div class="container narrow empty-state"><h1>PAGE NOT FOUND.</h1><p>Let’s help you find the right place.</p><div class="button-row">{link("/","BIT homepage")}{link("/programs/","Explore programs","text-link")}</div></div></section>'
write_page('/404/','Page not found','Find your way back to BIT’s programs and college information.',notfound)
